<script setup>
import { reactive,ref,onMounted,onBeforeUnmount,watch } from 'vue';
import { useRoute,useRouter } from 'vue-router';
import { api } from '../../services/api.js';
import { notify,confirmDialog } from '../../services/notifications.js';
import { useCollection,money,shortDate } from '../../services/panel.js';
import Icon from '../../components/Icon.vue';
import DataTable from '../../components/DataTable.vue';
const route=useRoute(),router=useRouter(),tab=ref(String(route.query.tab||'general')),loading=ref(true),saving=ref(false),error=ref(''),busyWa=ref(false),subscriptionIssues=ref([]),issuesLoading=ref(false),issueBusy=ref('');
const settings=reactive({trialDays:15,magicLinkMinutes:15,subscriptionGraceDays:7,subscriptionPendingLinkHours:24,platformBilling:{enabled:false,mercadopago:{sandbox:true,hasAccessToken:false,hasWebhookSecret:false,accessToken:'',webhookSecret:'',clearCredentials:false}},subscriptionWebhookUrl:'',legalUrls:{privacy:'',terms:''},contact:{email:'',phone:'',whatsapp:''},home:{eyebrow:'',title:'',subtitle:'',ctaText:'',heroImage:'',benefits:[],testimonials:[],faq:[]},legal:{privacy:{enabled:true,title:'',intro:'',updatedAt:'',sections:[]},terms:{enabled:true,title:'',intro:'',updatedAt:'',sections:[]}}});
const wa=reactive({status:'disconnected',qr:null,error:'',clientId:''});let polling;
const tabs=[['general','General','settings'],['planes','Planes','crown'],['suscripciones','Suscripciones','credit'],['contacto','Contacto','phone'],['whatsapp','WhatsApp','whatsapp'],['legal','Legales','shield'],['home','Página de inicio','home']];
const {rows,loading:plansLoading,error:plansError,meta,load:loadPlans,updateQuery}=useCollection('/admin/plans');
const planColumns=[{key:'name',label:'Plan'},{key:'inheritsPlan',label:'Herencia'},{key:'price',label:'Precio'},{key:'maxStores',label:'Tiendas'},{key:'maxProducts',label:'Productos'},{key:'maxPaymentMethods',label:'Pagos'},{key:'maxDeliveryMethods',label:'Entregas'},{key:'visible',label:'Visibilidad'},{key:'active',label:'Estado'}];
watch(tab,value=>{router.replace({query:{tab:value}});if(value==='whatsapp'){poll();polling=setInterval(poll,3000)}else{clearInterval(polling);polling=null}if(value==='suscripciones')loadSubscriptionIssues()});
onMounted(async()=>{try{const data=await api.get('/admin/settings');Object.assign(settings,data);settings.contact={email:'',phone:'',whatsapp:'',...data.contact};settings.home={eyebrow:'',title:'',subtitle:'',ctaText:'',heroImage:'',benefits:[],testimonials:[],faq:[],...data.home};settings.legal=normalizeLegal(data.legal);settings.legalUrls={privacy:'',terms:'',...data.legalUrls};settings.platformBilling={enabled:false,...data.platformBilling,mercadopago:{sandbox:true,hasAccessToken:false,hasWebhookSecret:false,accessToken:'',webhookSecret:'',clearCredentials:false,...data.platformBilling?.mercadopago}};settings.subscriptionWebhookUrl=data.subscriptionWebhookUrl||'';if(tab.value==='whatsapp'){poll();polling=setInterval(poll,3000)}if(tab.value==='suscripciones')await loadSubscriptionIssues()}catch(e){error.value=e.message}finally{loading.value=false}});
onBeforeUnmount(()=>clearInterval(polling));
async function save(){saving.value=true;error.value='';try{const mp=settings.platformBilling?.mercadopago||{};const legal=Object.fromEntries(['privacy','terms'].map(kind=>[kind,{enabled:Boolean(settings.legal[kind].enabled),title:settings.legal[kind].title,intro:settings.legal[kind].intro,sections:settings.legal[kind].sections.map(section=>({title:section.title,content:section.content}))}]));const payload={trialDays:settings.trialDays,magicLinkMinutes:settings.magicLinkMinutes,subscriptionGraceDays:settings.subscriptionGraceDays,subscriptionPendingLinkHours:settings.subscriptionPendingLinkHours,contact:settings.contact,home:settings.home,legal,platformBilling:{enabled:Boolean(settings.platformBilling?.enabled),mercadopago:{sandbox:mp.sandbox!==false,...(mp.accessToken?{accessToken:mp.accessToken}:{}),...(mp.webhookSecret?{webhookSecret:mp.webhookSecret}:{}),...(mp.clearCredentials?{clearCredentials:true}:{})}}};const data=await api.put('/admin/settings',payload);Object.assign(settings,data);settings.legal=normalizeLegal(data.legal);settings.legalUrls={privacy:'',terms:'',...data.legalUrls};settings.platformBilling={enabled:false,...data.platformBilling,mercadopago:{sandbox:true,accessToken:'',webhookSecret:'',clearCredentials:false,...data.platformBilling?.mercadopago}};notify.success('Configuración guardada.')}catch(e){error.value=e.message;notify.error(e.message)}finally{saving.value=false}}

async function loadSubscriptionIssues(){issuesLoading.value=true;try{subscriptionIssues.value=await api.get('/admin/subscription-support')}catch(e){notify.error(e.message)}finally{issuesLoading.value=false}}
async function approveSubscriptionIssue(row){if(!await confirmDialog({title:'Habilitar vendedor mientras se revisa Mercado Pago',message:`Se otorgará acceso manual por un período del plan ${row.planId?.name||''}. Mercado Pago seguirá mostrando su estado real hasta que confirme la vinculación.`,confirmText:'Habilitar'}))return;issueBusy.value=String(row._id);try{await api.post(`/admin/subscription-support/${row._id}/approve`,{});notify.success('Solicitud aprobada y acceso habilitado.');await loadSubscriptionIssues()}catch(e){notify.error(e.message)}finally{issueBusy.value=''}}
async function rejectSubscriptionIssue(row){if(!await confirmDialog({title:'Rechazar comprobante',message:'La solicitud quedará resuelta sin habilitar acceso manual.',confirmText:'Rechazar',danger:true}))return;issueBusy.value=String(row._id);try{await api.post(`/admin/subscription-support/${row._id}/reject`,{});notify.success('Solicitud rechazada.');await loadSubscriptionIssues()}catch(e){notify.error(e.message)}finally{issueBusy.value=''}}

async function clearSubscriptionCredentials(){if(!await confirmDialog({title:'Desvincular Mercado Pago de la plataforma',message:'Se eliminarán las credenciales usadas para nuevas suscripciones. Las suscripciones existentes no se modifican automáticamente en Mercado Pago.',confirmText:'Eliminar credenciales',danger:true}))return;settings.platformBilling.enabled=false;settings.platformBilling.mercadopago.clearCredentials=true;settings.platformBilling.mercadopago.accessToken='';settings.platformBilling.mercadopago.webhookSecret='';await save()}
async function removePlan(row){if(!await confirmDialog({title:'Desactivar plan',message:`El plan ${row.name} dejará de ofrecerse a nuevos vendedores. Revisá las asignaciones existentes antes de hacer cambios en sus límites.`,confirmText:'Desactivar',danger:true}))return;try{await api.delete(`/admin/plans/${row._id}`);notify.success('Plan desactivado.');loadPlans()}catch(e){notify.error(e.message)}}
async function poll(){try{Object.assign(wa,await api.get('/admin/whatsapp/status'))}catch(e){wa.error=e.message}}
async function connect(){busyWa.value=true;try{Object.assign(wa,await api.post('/admin/whatsapp/connect'));await poll();notify.info('Preparando WhatsApp. El QR aparecerá cuando esté disponible.')}catch(e){notify.error(e.message)}finally{busyWa.value=false}}
async function disconnect(){if(!await confirmDialog({title:'Desconectar WhatsApp',message:'Para volver a vincular la cuenta podría ser necesario escanear un nuevo QR.',confirmText:'Desconectar'}))return;busyWa.value=true;try{await api.post('/admin/whatsapp/disconnect');await poll();notify.success('WhatsApp desconectado.')}catch(e){notify.error(e.message)}finally{busyWa.value=false}}
const waLabels={disconnected:'Desconectado',connecting:'Preparando conexión',initializing:'Inicializando',qr:'Esperando escaneo',authenticated:'Autenticado',ready:'Conectado',connected:'Conectado',error:'Error de conexión',disabled:'Deshabilitado'};
function normalizeLegal(value={}){const make=kind=>({enabled:value?.[kind]?.enabled!==false,title:value?.[kind]?.title||'',intro:value?.[kind]?.intro||'',updatedAt:value?.[kind]?.updatedAt||'',sections:Array.isArray(value?.[kind]?.sections)?value[kind].sections.map(section=>({title:section.title||'',content:section.content||''})):[]});return {privacy:make('privacy'),terms:make('terms')}}
function addLegalSection(kind){if(settings.legal[kind].sections.length>=40)return;settings.legal[kind].sections.push({title:'Nueva sección',content:''})}
function removeLegalSection(kind,index){if(settings.legal[kind].sections.length<=1){notify.info('El documento debe conservar al menos una sección.');return}settings.legal[kind].sections.splice(index,1)}
</script>
<template><div><header class="p-page-header"><div><p class="p-eyebrow">A TU MEDIDA</p><h1>Configuración</h1><p>Definí cómo funciona y cómo se presenta MiTiendaYa.</p></div><a href="/" target="_blank" rel="noopener" class="btn btn-secondary"><Icon name="external" :size="15"/>Ver página de inicio</a></header><nav class="p-tabs" aria-label="Secciones de configuración"><button v-for="t in tabs" :key="t[0]" :class="{active:tab===t[0]}" @click="tab=t[0]"><Icon :name="t[2]" :size="16"/>{{t[1]}}</button></nav><div v-if="error" class="p-error">{{error}}</div><div v-if="loading" class="p-loading-page"><span class="p-spinner"/></div><template v-else>
 <section v-if="tab==='planes'"><div class="p-section-title"><div><h2>Planes comerciales</h2><p>Diseñá opciones para cada etapa del emprendimiento.</p></div><RouterLink to="/app/settings/plans/new" class="btn btn-primary"><Icon name="plus" :size="15"/>Crear plan</RouterLink></div><div v-if="plansError" class="p-error">{{plansError}}</div><DataTable :rows="rows" :columns="planColumns" :loading="plansLoading" server :total="meta.total" :page="meta.page" :limit="meta.limit" @query-change="updateQuery"><template #cell-name="{row}"><div class="p-product-cell"><span class="p-product-thumb"><Icon :name="row.icon"/></span><span><strong>{{row.name}}</strong><small>{{row.durationDays}} días <span v-if="row.featured">· Recomendado</span></small></span></div></template><template #cell-inheritsPlan="{row}"><span v-if="row.inheritsPlan" class="p-badge">Todo lo de {{row.inheritsPlan.name}}</span><span v-else class="p-muted">Sin herencia</span></template><template #cell-price="{row}"><strong>{{money(row.price)}}</strong><small v-if="row.previousPrice>row.price"><del>{{money(row.previousPrice)}}</del></small></template><template #cell-maxProducts="{value}">{{value===0?'Ilimitados':value}}</template><template #cell-maxPaymentMethods="{value}">{{value===0?'Sin límite':value}}</template><template #cell-maxDeliveryMethods="{value}">{{value===0?'Sin límite':value}}</template><template #cell-visible="{value}"><span class="p-badge" :class="value!==false?'green':'orange'">{{value!==false?'Público':'Oculto'}}</span></template><template #cell-active="{value}"><span class="p-badge" :class="value?'green':'red'">{{value?'Disponible':'Desactivado'}}</span></template><template #actions="{row}"><RouterLink :to="`/app/settings/plans/${row._id}`" class="p-icon-btn" title="Editar plan"><Icon name="edit" :size="14"/></RouterLink><button v-if="row.active" class="p-icon-btn danger" title="Desactivar plan" @click="removePlan(row)"><Icon name="trash" :size="14"/></button></template></DataTable></section>
 <section v-else-if="tab==='whatsapp'" class="p-section-card"><div class="p-section-title"><div><h2>WhatsApp de la plataforma</h2><p>Vinculá una cuenta desde WhatsApp → Dispositivos vinculados.</p></div><span class="p-badge" :class="['ready','connected'].includes(wa.status)?'green':'orange'">{{waLabels[wa.status]||wa.status}}</span></div><div class="p-two-column"><div><div class="p-info"><strong>Cómo vincular</strong><br/>1. Presioná Conectar y esperá a que aparezca el QR.<br/>2. Abrí WhatsApp en tu teléfono y entrá a Dispositivos vinculados.<br/>3. Elegí Vincular un dispositivo y escaneá el código.<br/>La conexión se verifica automáticamente cada 3 segundos.</div><p class="p-help">Instancia: <strong>{{wa.clientId||'Configurada en el servidor'}}</strong>. La sesión se conserva entre reinicios.</p><div v-if="wa.error" class="p-error">{{wa.error}}</div><div class="p-inline"><button class="btn btn-primary" :disabled="busyWa||['ready','connected','connecting','initializing','qr'].includes(wa.status)" @click="connect"><Icon name="whatsapp" :size="17"/>{{busyWa?'Procesando...':'Conectar WhatsApp'}}</button><button class="btn btn-secondary" :disabled="busyWa||wa.status==='disconnected'" @click="disconnect">Desconectar</button><button class="p-icon-btn" title="Actualizar estado" @click="poll"><Icon name="refresh" :size="16"/></button></div></div><div style="text-align:center"><img v-if="wa.qr" :src="wa.qr" class="p-qr" alt="Código QR para vincular WhatsApp"/><div v-else class="p-whatsapp-preview"><div><Icon name="whatsapp" :size="48"/><p>{{['ready','connected'].includes(wa.status)?'Tu cuenta está conectada.':'El código QR aparecerá acá.'}}</p><span v-if="['connecting','initializing'].includes(wa.status)" class="p-spinner"/></div></div></div></div></section>
 <form v-else @submit.prevent="save" class="p-form">
  <section v-if="tab==='general'" class="p-section-card"><div class="p-section-title"><div><h2>Acceso y período de prueba</h2><p>Estas reglas se aplican a nuevos accesos y nuevas pruebas.</p></div><Icon name="shield"/></div><div class="p-form-grid"><div class="p-field"><label for="trial-days">Días de prueba inicial</label><input id="trial-days" v-model.number="settings.trialDays" type="number" min="0" max="365" required/><small>0 deshabilita las pruebas nuevas. No modifica las pruebas que ya comenzaron.</small></div><div class="p-field"><label for="magic-minutes">Vigencia del enlace de ingreso (minutos)</label><input id="magic-minutes" v-model.number="settings.magicLinkMinutes" type="number" min="1" max="1440" required/><small>Cada enlace puede usarse una sola vez. Los vendedores pueden solicitar uno nuevo.</small></div></div></section>
  <template v-else-if="tab==='suscripciones'"><section class="p-section-card"><div class="p-section-title"><div><h2>Suscripciones de vendedores</h2><p>Configurá el cobro recurrente de los planes de la plataforma con Mercado Pago.</p></div><Icon name="credit"/></div><div class="p-form-grid"><div class="p-field full"><label class="p-tag-option"><input v-model="settings.platformBilling.enabled" type="checkbox"/><span><strong>Habilitar contratación automática</strong></span></label><small>Los vendedores podrán suscribirse a los planes activos desde Mi suscripción.</small></div><div class="p-field"><label for="subscription-grace">Días de cortesía por falta de pago</label><input id="subscription-grace" v-model.number="settings.subscriptionGraceDays" type="number" min="0" max="3650" required/><small>Durante este período las tiendas siguen publicadas aunque existan períodos adeudados.</small></div><div class="p-field"><label for="subscription-pending-hours">Horas máximas para completar una vinculación</label><input id="subscription-pending-hours" v-model.number="settings.subscriptionPendingLinkHours" type="number" min="1" max="720" required/><small>Al vencer, MiTiendaYa cancela automáticamente el intento pendiente en Mercado Pago. El valor se fija cuando se crea cada vinculación.</small></div><div class="p-field"><label for="subscription-sandbox">Entorno</label><select id="subscription-sandbox" v-model="settings.platformBilling.mercadopago.sandbox"><option :value="true">Pruebas / sandbox</option><option :value="false">Producción</option></select></div><div class="p-field"><label for="platform-mp-token">Access Token de Mercado Pago</label><input id="platform-mp-token" v-model.trim="settings.platformBilling.mercadopago.accessToken" type="password" autocomplete="new-password" :placeholder="settings.platformBilling.mercadopago.hasAccessToken?'Configurado · dejá vacío para conservar':'APP_USR-…'"/><small>Credencial de la cuenta de Mercado Pago de MiTiendaYa que cobrará las suscripciones.</small></div><div class="p-field"><label for="platform-mp-webhook">Clave secreta de Webhooks</label><input id="platform-mp-webhook" v-model.trim="settings.platformBilling.mercadopago.webhookSecret" type="password" autocomplete="new-password" :placeholder="settings.platformBilling.mercadopago.hasWebhookSecret?'Configurada · dejá vacío para conservar':'Clave secreta'"/><small>Usada para validar que los eventos de suscripción realmente provienen de Mercado Pago.</small></div><div class="p-field full"><label for="subscription-webhook-url">URL de Webhook</label><input id="subscription-webhook-url" :value="settings.subscriptionWebhookUrl" readonly/><small>Registrá esta URL para los eventos de suscripciones y pagos autorizados en Mercado Pago.</small></div></div><div class="p-inline" style="margin-top:18px"><span class="p-badge" :class="settings.platformBilling.mercadopago.hasAccessToken&&settings.platformBilling.mercadopago.hasWebhookSecret?'green':'orange'">{{settings.platformBilling.mercadopago.hasAccessToken&&settings.platformBilling.mercadopago.hasWebhookSecret?'Credenciales configuradas':'Configuración incompleta'}}</span><button v-if="settings.platformBilling.mercadopago.hasAccessToken||settings.platformBilling.mercadopago.hasWebhookSecret" type="button" class="btn btn-secondary" @click="clearSubscriptionCredentials">Eliminar credenciales</button></div></section><section class="p-section-card"><div class="p-section-title"><div><h2>Comprobantes para revisar</h2><p>Vendedores que indican haber completado la vinculación pero Mercado Pago todavía la informa como pendiente.</p></div><button type="button" class="btn btn-secondary btn-small" :disabled="issuesLoading" @click="loadSubscriptionIssues"><Icon name="refresh" :size="14"/>Actualizar</button></div><div v-if="issuesLoading" class="p-loading-page"><span class="p-spinner"/></div><div v-else-if="!subscriptionIssues.length" class="p-info">No hay comprobantes pendientes de revisión.</div><div v-else class="p-stack"><article v-for="item in subscriptionIssues" :key="item._id" class="p-nested-card"><header><div><strong>{{item.userId?.name||item.userId?.email||'Vendedor'}}</strong><small>{{item.userId?.email}} · {{item.planId?.name||'Plan'}} · enviado {{shortDate(item.createdAt)}}</small></div><span class="p-badge orange">Revisión pendiente</span></header><p v-if="item.note" class="p-help">{{item.note}}</p><div class="p-inline"><a :href="`/api/admin/subscription-support/${item._id}/receipt`" target="_blank" rel="noopener" class="btn btn-secondary btn-small"><Icon name="receipt" :size="14"/>Ver comprobante</a><button type="button" class="btn btn-primary btn-small" :disabled="issueBusy===String(item._id)" @click="approveSubscriptionIssue(item)">Habilitar por un período</button><button type="button" class="btn btn-secondary btn-small" :disabled="issueBusy===String(item._id)" @click="rejectSubscriptionIssue(item)">Rechazar</button></div></article></div></section></template>
  <section v-else-if="tab==='contacto'" class="p-section-card"><div class="p-section-title"><div><h2>Contacto con MiTiendaYa</h2><p>Se muestra en la página de inicio y en la sección Mi suscripción.</p></div><Icon name="phone"/></div><div class="p-form-grid"><div class="p-field"><label for="platform-email">Correo de contacto</label><input id="platform-email" v-model.trim="settings.contact.email" type="email" placeholder="hola@tu-dominio.com"/></div><div class="p-field"><label for="platform-phone">Teléfono visible</label><input id="platform-phone" v-model.trim="settings.contact.phone" type="tel" placeholder="+54 11 1234 5678"/></div><div class="p-field"><label for="platform-wa">WhatsApp de soporte y planes</label><input id="platform-wa" v-model.trim="settings.contact.whatsapp" type="tel" placeholder="5491112345678"/><small>Incluí código de país y área. Se utiliza para abrir una conversación.</small></div></div></section>
  <template v-else-if="tab==='legal'"><section class="p-section-card"><div class="p-section-title"><div><h2>Documentos legales de la aplicación</h2><p>Estos textos son globales para MiTiendaYa y se publican como páginas independientes. La fecha de última actualización se renueva automáticamente al guardar cambios.</p></div><Icon name="shield"/></div><div class="p-info"><strong>Importante:</strong> el contenido inicial cubre las funciones actuales de MiTiendaYa y sus principales medidas de seguridad. Antes de una publicación comercial definitiva, conviene que un profesional legal lo revise para tu situación societaria, fiscal y jurisdiccional concreta.</div></section><section v-for="kind in ['privacy','terms']" :key="kind" class="p-section-card"><div class="p-section-title"><div><h2>{{kind==='privacy'?'Política de privacidad de la aplicación':'Condiciones del servicio de la aplicación'}}</h2><p>Última actualización: <strong>{{settings.legal[kind].updatedAt||'se asignará al guardar'}}</strong></p></div><a :href="settings.legalUrls[kind]||(kind==='privacy'?'/politica-de-privacidad':'/condiciones-del-servicio')" target="_blank" rel="noopener" class="btn btn-secondary btn-small"><Icon name="external" :size="14"/>Ver página</a></div><div class="p-form-grid"><div class="p-field full"><label class="p-tag-option"><input v-model="settings.legal[kind].enabled" type="checkbox"/><span><strong>Publicar este documento</strong></span></label><small>Si lo desactivás, la URL pública devolverá que el documento no está publicado y dejará de mostrarse en el pie de la página de inicio.</small></div><div class="p-field full"><label :for="`legal-${kind}-title`">Título</label><input :id="`legal-${kind}-title`" v-model.trim="settings.legal[kind].title" maxlength="240" required/></div><div class="p-field full"><label :for="`legal-${kind}-intro`">Introducción</label><textarea :id="`legal-${kind}-intro`" v-model.trim="settings.legal[kind].intro" maxlength="5000" rows="4" required/><small>Resumen que aparece debajo del título principal.</small></div></div><div class="p-section-title" style="margin-top:28px"><div><h3>Secciones del documento</h3><p>Se muestran en el mismo orden en la página pública y forman automáticamente el índice lateral.</p></div></div><div v-for="(section,index) in settings.legal[kind].sections" :key="`${kind}-${index}`" class="p-nested-card"><header><strong>Sección {{index+1}}</strong><button type="button" class="p-icon-btn danger" title="Quitar sección" :disabled="settings.legal[kind].sections.length<=1" @click="removeLegalSection(kind,index)"><Icon name="trash" :size="14"/></button></header><div class="p-form-grid"><div class="p-field full"><label :for="`legal-${kind}-section-${index}-title`">Título de la sección</label><input :id="`legal-${kind}-section-${index}-title`" v-model.trim="section.title" maxlength="220" required/></div><div class="p-field full"><label :for="`legal-${kind}-section-${index}-content`">Contenido</label><textarea :id="`legal-${kind}-section-${index}-content`" v-model="section.content" maxlength="15000" rows="7" required/><small>Texto plano. Los saltos de línea se respetan en la página pública; no se interpreta HTML.</small></div></div></div><button type="button" class="p-add-dashed" :disabled="settings.legal[kind].sections.length>=40" @click="addLegalSection(kind)"><Icon name="plus" :size="15"/>Agregar sección</button></section></template>
  <template v-else-if="tab==='home'"><section class="p-section-card"><div class="p-section-title"><div><h2>Portada de la plataforma</h2><p>Una primera impresión que invite a emprender.</p></div><Icon name="home"/></div><div class="p-form-grid"><div class="p-field full"><label for="home-eyebrow">Texto destacado sobre el título</label><input id="home-eyebrow" v-model="settings.home.eyebrow" maxlength="100"/></div><div class="p-field full"><label for="home-title">Título principal</label><input id="home-title" v-model="settings.home.title" required maxlength="180"/></div><div class="p-field full"><label for="home-subtitle">Descripción principal</label><textarea id="home-subtitle" v-model="settings.home.subtitle" maxlength="1000" rows="3"/></div><div class="p-field"><label for="home-cta">Texto del botón para empezar</label><input id="home-cta" v-model="settings.home.ctaText" maxlength="60"/></div><div class="p-field"><label for="home-hero">Imagen de portada (URL HTTPS)</label><input id="home-hero" v-model.trim="settings.home.heroImage" type="url" placeholder="https://..."/><small>Opcional. Elegí una imagen sobre la que tengas derechos de uso.</small></div></div></section><section class="p-section-card"><div class="p-section-title"><div><h2>Beneficios de la plataforma</h2><p>Mostrá qué hace más simple el día a día.</p></div></div><div v-for="(b,i) in settings.home.benefits" :key="i" class="p-nested-card"><header><strong>Beneficio {{i+1}}</strong><button type="button" class="p-icon-btn danger" title="Quitar beneficio" @click="settings.home.benefits.splice(i,1)"><Icon name="trash" :size="14"/></button></header><div class="p-form-grid"><div class="p-field"><label :for="`benefit-title-${i}`">Título</label><input :id="`benefit-title-${i}`" v-model="b.title" required maxlength="100"/></div><div class="p-field"><label :for="`benefit-icon-${i}`">Ícono</label><select :id="`benefit-icon-${i}`" v-model="b.icon"><option v-for="icon in ['store','palette','credit','credit-card','package','chart','phone','shield','truck','sparkles']" :key="icon">{{icon}}</option></select></div><div class="p-field full"><label :for="`benefit-desc-${i}`">Descripción</label><textarea :id="`benefit-desc-${i}`" v-model="b.description" rows="2" maxlength="600"/></div></div></div><button type="button" class="p-add-dashed" :disabled="settings.home.benefits.length>=12" @click="settings.home.benefits.push({title:'',description:'',icon:'sparkles'})"><Icon name="plus" :size="15"/>Agregar beneficio</button></section><section class="p-section-card"><div class="p-section-title"><div><h2>Experiencias de vendedores</h2><p>Publicá testimonios reales con autorización de sus autores.</p></div></div><div v-for="(t,i) in settings.home.testimonials" :key="i" class="p-nested-card"><header><strong>Experiencia {{i+1}}</strong><button type="button" class="p-icon-btn danger" title="Quitar experiencia" @click="settings.home.testimonials.splice(i,1)"><Icon name="trash" :size="14"/></button></header><div class="p-form-grid"><div class="p-field"><label :for="`test-name-${i}`">Nombre</label><input :id="`test-name-${i}`" v-model="t.name" required maxlength="100"/></div><div class="p-field"><label :for="`test-business-${i}`">Emprendimiento</label><input :id="`test-business-${i}`" v-model="t.business" maxlength="120"/></div><div class="p-field full"><label :for="`test-quote-${i}`">Testimonio</label><textarea :id="`test-quote-${i}`" v-model="t.quote" required rows="3" maxlength="1500"/></div></div></div><button type="button" class="p-add-dashed" :disabled="settings.home.testimonials.length>=20" @click="settings.home.testimonials.push({name:'',business:'',quote:''})"><Icon name="plus" :size="15"/>Agregar experiencia</button></section><section class="p-section-card"><div class="p-section-title"><h2>Preguntas frecuentes</h2></div><div v-for="(f,i) in settings.home.faq" :key="i" class="p-nested-card"><header><strong>Pregunta {{i+1}}</strong><button type="button" class="p-icon-btn danger" title="Quitar pregunta" @click="settings.home.faq.splice(i,1)"><Icon name="trash" :size="14"/></button></header><div class="p-form-grid"><div class="p-field full"><label :for="`faq-question-${i}`">Pregunta</label><input :id="`faq-question-${i}`" v-model="f.question" required maxlength="300"/></div><div class="p-field full"><label :for="`faq-answer-${i}`">Respuesta</label><textarea :id="`faq-answer-${i}`" v-model="f.answer" required maxlength="2000" rows="3"/></div></div></div><button type="button" class="p-add-dashed" :disabled="settings.home.faq.length>=30" @click="settings.home.faq.push({question:'',answer:''})"><Icon name="plus" :size="15"/>Agregar pregunta</button></section></template><footer class="p-form-footer"><small>Guardá para aplicar los cambios de configuración.</small><div class="p-form-actions"><button class="btn btn-primary" :disabled="saving">{{saving?'Guardando...':'Guardar configuración'}}</button></div></footer>
 </form></template></div></template>
